select
admin.*
from admin admin

    and admin.id = #{id}
    and admin.user_name = #{userName}
    and admin.pass_word = #{passWord}
    and admin.head_img = #{headImg}
    and admin.nick_name like concat('%',#{nickName},'%')
    and admin.create_time = #{createTime}


    limit #{current},#{pageSize}

select count(*) from admin admin

    and admin.id = #{id}
    and admin.user_name = #{userName}
    and admin.pass_word = #{passWord}
    and admin.head_img = #{headImg}
    and admin.nick_name like concat('%',#{nickName},'%')
    and admin.create_time = #{createTime}
